export function refreshTaskAcceptance(categories) {
  for (const category of categories) {
    if (categories.some((child) => child.parentCode === category.code && child.open)) {
      category.acceptsTasks = false;
    }
  }
}

export function upgradeCategories(categories, nextTemplate) {
  const byCode = new Map(categories.map((category) => [category.code, category]));
  for (const template of nextTemplate) {
    const local = byCode.get(template.code);
    if (local) local.acceptsTasks = template.acceptsTasks;
  }
}

