import { expect, test } from "bun:test";
import { refreshTaskAcceptance, upgradeCategories } from "./categories.js";

test("a parent closed by an open child stays closed after a template upgrade", () => {
  const parent = { code: "work", acceptsTasks: true };
  const categories = [parent, { code: "work/meetings", parentCode: "work", open: true }];
  refreshTaskAcceptance(categories);
  expect(parent.acceptsTasks).toBe(false);

  upgradeCategories(categories, [{ code: "work", acceptsTasks: true }]);

  expect(parent.acceptsTasks).toBe(false);
});

test("a category without open children can accept tasks after a template upgrade", () => {
  const parent = { code: "work", acceptsTasks: false };

  upgradeCategories([parent], [{ code: "work", acceptsTasks: true }]);

  expect(parent.acceptsTasks).toBe(true);
});
